import{_ as n,l as o,o as e,c as s,v as t,p as l,x as r,d as E,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"流量工程","description":"","frontmatter":{"title":"流量工程","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/traffic-engineering.md","filePath":"cs/traffic-engineering.md","lastUpdated":1789023840000}'),P={name:"cs/traffic-engineering.md"};function c(h,a,T,S,_,f){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="流量工程" tabindex="-1">流量工程 <a class="header-anchor" href="#流量工程" aria-label="Permalink to &quot;流量工程&quot;">​</a></h1><div class="epigraph"><p>最短 IGP 度量会把流量堆到最宽的树上；流量工程用另一套约束（带宽、时延、着色）把需求矩阵搬到链路上，使热点下降。</p><footer>—— 据 RFC 3272 综述；OSPF-TE / RSVP-TE 实践；Kurose and Ross TE 节整理</footer></div><p><a href="/cs/internet-ixp">上一课</a> 画出 AS 图。域内同样会挤：ECMP 哈希仍可能打满一条。缺口是<strong>流量工程</strong>：与「最短路」分离的显式路由或度量调整。本课不把 MPLS 标签栈写完，下一课才是 MPLS。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OSPF 代价若只按接口带宽设，所有需求仍可能共享同一条低代价边。TE：测量需求 → 算约束最短路或多商品流近似 → 用 RSVP-TE 建 LSP，或调 IGP 度量，或用后课 SR。目标常是最大链路利用率最小，不是单流跳数最小。与 HOL：那是微秒级结构；TE 是分钟到小时的矩阵。</p><p>不要把 TE 写成「买更大的口」唯一解：口更大后最短树仍可能挤。</p><p><span class="marginnote">RFC 3272。Fortz–Thorup 等讨论度量优化。本课不解整数多商品流。</span></p><h3 id="最短树会堆热点" tabindex="-1">最短树会堆热点 <a class="header-anchor" href="#最短树会堆热点" aria-label="Permalink to &quot;最短树会堆热点&quot;">​</a></h3><p>度量、LSP 或 SR 把需求矩阵搬开。过频调度量会抖 IGP。域间 TE 是属性，不是 Dijkstra。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：调度量（全局副作用）vs 显式 LSP（局部）。画：需求矩阵 → 约束 → 转发路径。IXP 出口选择是域间 TE：MED、AS-PATH prepend、更长前缀（谨慎，RPKI maxLength）。</p>',11)),(e(),l(d,null,{default:r(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEM%5B%22%E9%9C%80%E6%B1%82%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20CST%5B%22%E5%B8%A6%E5%AE%BD%2F%E6%97%B6%E5%BB%B6%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20CST%20--%3E%20PATH%5B%22%E6%98%BE%E5%BC%8F%E6%88%96%E8%B0%83%E5%BA%A6%E9%87%8F%22%5D%0A%20%20PATH%20--%3E%20UTIL%5B%22%E9%99%8D%E7%83%AD%E7%82%B9%E5%88%A9%E7%94%A8%E7%8E%87%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>BGP 决策仍选出口；TE 决定出口之后域内怎么走。卫星链路带宽贵，TE 更要避开误码高的入口。切片 5G 是无线侧预留；这里是 IP/MPLS 预留，对象类似、层不同。</p><p>ECMP 是无状态分流，TE 可以有状态；后课会对比 SR 的无状态中间节点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 PCE 的全部 PCEP。MPLS 是下一课。后课默认：TE 把约束放进选路，IGP 最短只是其中一个解。</p><p>过频调度量会引起 IGP 与 BGP 震荡，像人为抖动。</p><p>上一课留下的缺口在本课收口；「流量工程」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/mpls">MPLS</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最短 IGP 树不等于均衡负载。</li><li>TE 用度量、LSP 或后课 SR 搬流量。</li><li>域间 TE 是政策属性，不是 Dijkstra。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 3272；OSPF-TE 实践。</li></ul>',10))])}const A=n(P,[["render",c]]);export{u as __pageData,A as default};
